define(["core/ajax","core/notification","mod_bookflow/progress_tracker"],function(Ajax,Notification,ProgressTracker){const init=function(bookflowId){document.addEventListener("submit",function(event){const form=event.target.closest("[data-bookflow-question]");if(!form){return}event.preventDefault();const selected=form.querySelector("input[name='answer']:checked");if(!selected){return}Ajax.call([{methodname:"bookflowcontent_question_submit_answer",args:{bookflowid:bookflowId,contentid:Number(form.dataset.bookflowQuestion),answer:JSON.stringify(selected.value)}}])[0].then(function(result){const feedback=form.querySelector("[data-region='question-feedback']");if(feedback){feedback.textContent=result.feedback}return Ajax.call([{methodname:"mod_bookflow_get_user_progress",args:{bookflowid:bookflowId}}])[0]}).then(ProgressTracker.updateProgress).catch(Notification.exception)})};return{init:init}});